<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Đăng nhập Admin</title>@vite(['resources/css/app.css','resources/js/app.js'])</head><body class="grid min-h-screen place-items-center bg-brand-900 p-5"><form id="login-form" class="w-full max-w-md rounded-3xl bg-white p-9 shadow-2xl"><div class="text-2xl font-black text-brand-900">DENTAL<span class="text-brand-500">TOUR</span></div><h1 class="mt-8 text-3xl font-black">Admin CMS</h1><p class="mt-2 text-sm text-slate-500">Đăng nhập để quản lý nội dung và lead.</p><p id="error" class="mt-4 hidden rounded-lg bg-red-50 p-3 text-sm text-red-700"></p><label class="mt-6 block text-sm font-bold">Email<input name="email" type="email" required class="mt-2 w-full rounded-xl border border-slate-200 px-4 py-3 outline-none focus:border-brand-500"></label><label class="mt-4 block text-sm font-bold">Mật khẩu<input name="password" type="password" required class="mt-2 w-full rounded-xl border border-slate-200 px-4 py-3 outline-none focus:border-brand-500"></label><button class="mt-6 w-full rounded-xl bg-brand-600 px-5 py-3 font-bold text-white">Đăng nhập</button></form><script>document.getElementById('login-form').addEventListener('submit',async(e)=>{e.preventDefault();const error=document.getElementById('error');error.classList.add('hidden');const response=await fetch('/api/admin/auth/login',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});if(response.ok){location.href='{{ route('admin.dashboard') }}';return;}const data=await response.json();error.textContent=data.message||Object.values(data.errors||{}).flat()[0]||'Không thể đăng nhập.';error.classList.remove('hidden');});</script></body></html>
